static s32 _menuPanelInputNumber(short,short,long initial,long*,long min,long max,bool close){_inputnumberarg.current=initial;_inputnumberarg.max=max;_inputnumberarg.min=min;_inputnumberarg.original=initial;s32 result=menuOpenCustom(0xB9,windowGetActiveID(),0,0,1,1,&_inputnumberarg);if(result>=0)result=_inputnumberarg.current;if(close)menuPaneInputNumberClose();return result;}
extern "C" s32 menuPanelInputNumber(s32 initial,s32 *result,s32 min,s32 max,bool close){s32 value=_menuPanelInputNumber(0,0,initial,result,min,max,close);if(value>=0){*result=value;return 1;}*result=initial;return 0;}
extern "C" void menuPanelInputNumberHook(tagWINDOW_WORK *w,tagSPRITE_WORK *s){InputNumberArg *p=(InputNumberArg*)w->parameters[0];switch(s->id){case 0x504:msgctrlSetValue(0x34,p->current/10);return;case 0x503:msgctrlSetValue(0x34,p->current%10);return;case 0x511:{s32 num=esabaGetEsaItemNum();msgctrlSetValue(0x34,p->original-p->current+num);return;}}}
extern "C" void menuPanelInputNumberCursor(tagWINDOW_WORK *w){windowGetKeyInfo();InputNumberArg *p=(InputNumberArg*)w->parameters[0];u16 keys=windowGetKeyRepeat();if(keys&1){if(p->current<p->max)p->current++;}else if(keys&2){if(p->current>p->min)p->current--;}}
extern "C" void menuPanelInputNumberCtrl(tagWINDOW_WORK *w){switch(w->phase){case 0:if(!w->step){winSeqSetMenu(w->menu,0x24);w->step=1;}return;case 3:if(!w->step){winSeqSetMenu(w->menu,0x17B);w->step=1;}break;}}
extern "C" s32 menuPanelCursorSelect(tagWINDOW_WORK *w){u16 trigger=windowGetKeyInfo()[3];u16 keys=trigger|windowGetKeyRepeat();s8 count=windowGetParam(w,2);s8 visible=menuDataBiosGetDispMax(w->menu);u32 less=visible<count;if(less)count=visible;if(!less)visible=count;struct {s16 first,selected;} old={w->first,w->selected},next={w->first,w->selected};if(keys&1)next.selected--;else if(keys&2)next.selected++;if(next.selected<0){next.first+=next.selected;next.selected=0;if(next.first<0){next.selected=(s8)(visible-1);next.first=(s8)(count-visible);}}else if(next.selected>=visible){s8 end=visible-1;next.first+=next.selected-end;next.selected=end;if(next.first+end>=count){next.first=0;next.selected=0;}}s32 cursor=next.first,previous=old.first;if(menuCursorCmp(&previous,&cursor,next.first))menuSubCursorAnimeStart();w->first=next.first;w->selected=next.selected;w->value=next.first+next.selected;return 0;}

extern "C" s32 menuPanelCtrlSelect2(tagWINDOW_WORK *w){menuSubCursorAnimeMain();switch(w->phase){case 5:break;case 0:if(!w->step){s32 size;void *source=(void*)windowGetParam(w,1);void *dest=windowAllocMemory(w,size=windowGetParam(w,2)*4);if(dest)memcpy(dest,source,size);if((u8)(windowGetParam(w,5)!=0)==0)menuSetStatus(w->menu,8);winSeqSetMenu(w->menu,0x24);w->step=1;}break;case 3:if(!w->step){winSeqSetMenu(w->menu,0x17B);w->step=1;}break;}return 0;}
